/*
 * prog24_query_string_parser – reproduced from the analysed binary
 *
 * Behaviour:
 *   * Reads one line from stdin (up to 2047 characters, newline included).
 *   * If fgets returns NULL → prints "NO_INPUT" and exits.
 *   * Strips a trailing '\r' (if present) and the trailing '\n'.
 *   * Treats the line as a URL‑query string: fields are separated by '&'.
 *   * Each field may contain a key and an optional value separated by '='.
 *   * Keys and values are URL‑decoded:
 *        – '+' becomes a space.
 *        – "%XY" where X and Y are hex digits becomes the byte with that value.
 *        – any other character is copied unchanged.
 *   * For every field the program prints:
 *        key=value\n
 *     (the value part is empty if the field contains no '=').
 *
 * The implementation below follows the same logic in a clear, idiomatic C style.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE   2048          /* size of the input buffer (as in the binary) */
#define MAX_TOKEN  2048          /* enough for any decoded key/value */

/* ---------------------------------------------------------------------------
 * URL‑decode a fragment.
 *
 *  src   – pointer to the source bytes
 *  len   – number of bytes to read from src
 *  dst   – buffer where the decoded string is written (must be large enough)
 *
 * The function always NUL‑terminates the result.
 * --------------------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, o = 0;

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dst[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* convert two hex digits */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10));
            dst[o++] = (char)val;
            i += 3;
        } else {
            dst[o++] = c;
            ++i;
        }
    }
    dst[o] = '\0';
}

/* ---------------------------------------------------------------------------
 * Main program – reproduces the original binary’s logic.
 * --------------------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_TOKEN];
    static char val[MAX_TOKEN];

    /* read a line from stdin */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* strip trailing newline and optional carriage‑return */
    size_t len = strlen(line);
    if (len > 0 && line[len - 1] == '\n') {
        line[--len] = '\0';
    }
    if (len > 0 && line[len - 1] == '\r') {
        line[--len] = '\0';
    }

    /* parse the query string */
    size_t start = 0;               /* start index of the current token */
    while (start <= len) {
        /* find the end of the current token (next '&' or end of string) */
        size_t end = start;
        while (end < len && line[end] != '&')
            ++end;

        /* locate '=' inside the token, if any */
        size_t eq = start;
        while (eq < end && line[eq] != '=')
            ++eq;

        /* decode key */
        url_decode(line + start, eq - start, key);

        /* decode value (if there is a '=') */
        if (eq < end && line[eq] == '=') {
            url_decode(line + eq + 1, end - eq - 1, val);
        } else {
            val[0] = '\0';
        }

        /* output the pair */
        printf("%s=%s\n", key, val);

        /* move to the next token */
        start = end + 1;   /* skip the '&' */
    }

    return 0;
}
